const body = $input.first().json.body || $input.first().json;
const event = $input.first().json.headers ? $input.first().json.headers['x-github-event'] : 'event';

let message = '';
let title = 'GitHub';

if (event === 'pull_request') {
  const action = body.action;
  const pr = body.pull_request || {};
  const repo = body.repository ? body.repository.name : 'your repo';
  if (action === 'closed' && pr.merged) {
    message = `Prateek, Pull request #${pr.number} was successfully merged into ${repo}!`;
  } else {
    message = `Pull request #${pr.number} in ${repo} was ${action}.`;
  }
} else if (event === 'push') {
  const pusher = body.pusher ? body.pusher.name : 'Developer';
  const repo = body.repository ? body.repository.name : 'repository';
  message = `${pusher} pushed new commits to ${repo}.`;
} else {
  message = `New GitHub activity recorded on your repository.`;
}

return [{
  json: {
    title: title,
    message: message,
    speak: true,
    show_hud: true
  }
}];
